<?php
declare(strict_types=1);
function size_monitor_schema(PDO $db):void {
 $db->exec("CREATE TABLE IF NOT EXISTS size_monitor_state(id INTEGER PRIMARY KEY CHECK(id=1),started_at TEXT NOT NULL,last_sync TEXT NOT NULL DEFAULT '',source_error TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS size_monitor_orders(id INTEGER PRIMARY KEY,eligible INTEGER NOT NULL,first_seen TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS size_monitor_aliases(alias TEXT PRIMARY KEY,order_id INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS size_monitor_assignments(order_id INTEGER NOT NULL,sku TEXT NOT NULL,version_id INTEGER NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(order_id,sku))");
 size_versions_schema($db);$cols=array_column($db->query('PRAGMA table_info(size_chart_versions)')->fetchAll(PDO::FETCH_ASSOC),'name');foreach(['applied_at','ended_at','source_hash'] as $col)if(!in_array($col,$cols,true))$db->exec("ALTER TABLE size_chart_versions ADD COLUMN $col TEXT NOT NULL DEFAULT ''");
}
function size_monitor_aliases(array $r):array {$a=[];if(trim($r['rowId']??'')!=='')$a[]='row:'.$r['rowId'];if(($t=stock_tracking($r['tracking']??''))!=='')$a[]='tracking:'.$t;if(!$a)$a[]='position:'.($r['sheetId']??'').'|'.($r['row']??0);return $a;}
function size_monitor_enroll(PDO $db,array $rows,bool $baseline=false,bool $changed=false,?string $now=null):array {
 size_monitor_schema($db);$state=$db->query('SELECT * FROM size_monitor_state WHERE id=1')->fetch(PDO::FETCH_ASSOC);if(!$state)return $rows;$now??=gmdate('c');$owned=!$db->inTransaction();if($owned)$db->beginTransaction();try{$day=(new DateTimeImmutable($state['started_at']))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d');$versions=$db->query('SELECT * FROM size_chart_versions ORDER BY applied_at DESC,id DESC')->fetchAll(PDO::FETCH_ASSOC);$find=$db->prepare('SELECT o.* FROM size_monitor_aliases a JOIN size_monitor_orders o ON o.id=a.order_id WHERE a.alias=?');$link=$db->prepare('INSERT OR IGNORE INTO size_monitor_aliases VALUES(?,?)');$save=$db->prepare('INSERT INTO size_monitor_orders(eligible,first_seen) VALUES(?,?)');$af=$db->prepare('SELECT * FROM size_monitor_assignments WHERE order_id=? AND sku=?');$as=$db->prepare('INSERT INTO size_monitor_assignments VALUES(?,?,?,?)');$out=[];
 foreach($rows as $r){$aliases=size_monitor_aliases($r);$order=null;foreach($aliases as $a){$find->execute([$a]);if($candidate=$find->fetch(PDO::FETCH_ASSOC)){if(!$order||!(int)$candidate['eligible'])$order=$candidate;}}
  if(!$order){$stable=!str_starts_with($aliases[0],'position:');$eligible=!$baseline&&$stable&&(($r['date']??'')===''||$r['date']>=$day);$save->execute([(int)$eligible,$now]);$order=['id'=>(int)$db->lastInsertId(),'eligible'=>(int)$eligible,'first_seen'=>$now];}foreach($aliases as $a)$link->execute([$a,$order['id']]);if(!$order['eligible'])continue;
  $r['sizeDate']=(new DateTimeImmutable($order['first_seen']))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d');$r['sizeCharts']=[];$r['sizeMonitorFirstSeen']=$order['first_seen'];
  foreach(array_unique(array_column($r['items'],'sku')) as $sku){$af->execute([$order['id'],$sku]);$assignment=$af->fetch(PDO::FETCH_ASSOC);if(!$assignment){$v=null;$reason=$changed?'Đơn xuất hiện trong khoảng phát hiện đổi bảng size, cần xác nhận phiên bản.':'Chưa có bảng size được xác minh khi đơn xuất hiện.';if(!$changed)foreach($versions as $candidate)if($candidate['sku']===$sku&&$candidate['applied_at']!==''&&$candidate['applied_at']<=$order['first_seen']&&($candidate['ended_at']===''||$order['first_seen']<$candidate['ended_at'])){$v=$candidate;break;}$assignment=['version_id'=>(int)($v['id']??0),'reason'=>$v?'':$reason];$as->execute([$order['id'],$sku,$assignment['version_id'],$assignment['reason']]);}if($assignment['version_id'])foreach($versions as $v)if((int)$v['id']===(int)$assignment['version_id']){$r['sizeCharts'][$sku]=['id'=>(int)$v['id'],'name'=>$v['name'],'from'=>$v['applied_at'],'to'=>$v['ended_at']];break;}if(!$assignment['version_id'])$r['sizeMonitorUnassigned'][$sku]=$assignment['reason'];}
  $out[]=$r;
 }if($owned)$db->commit();return $out;}catch(Throwable $e){if($owned&&$db->inTransaction())$db->rollBack();throw $e;}
}
function size_monitor_start(PDO $db,array $rows):array {
 size_monitor_schema($db);$db->beginTransaction();try{if(!$db->query('SELECT COUNT(*) FROM size_monitor_state')->fetchColumn()){$db->prepare('INSERT INTO size_monitor_state(id,started_at) VALUES(1,?)')->execute([gmdate('c')]);size_monitor_enroll($db,$rows,true);}$db->commit();return $db->query('SELECT * FROM size_monitor_state')->fetch(PDO::FETCH_ASSOC);}catch(Throwable $e){$db->rollBack();throw $e;}
}
function size_source_blocks(array $sheet):array {
 $get=static fn($r,$c)=>trim((string)($sheet[$r][$c]??''));$range=static fn($v)=>preg_match('/^(?:[<>=≤≥]*\s*)?\d+(?:\s*[-–]\s*\d+)?\+{0,2}$/u',$v);$result=[];
 foreach($sheet as $r=>$row)foreach($row as $c=>$title){$title=trim($title);if(!preg_match('/^BẢNG SIZE/iu',$title)||preg_match('/(?:\bcũ\b|\bcu\b)/iu',$title))continue;preg_match_all('/\b[A-Z]{1,8}\d{1,6}\b/u',mb_strtoupper($title,'UTF-8'),$codes);if(!$codes[0])continue;$h=$r;while($h<min(count($sheet),$r+4)&&!$range($get($h,$c+1)))$h++;if($h>=min(count($sheet),$r+4))throw new RuntimeException('Thiếu cột cân nặng: '.$title);$cols=[];for($i=$c+1;$range($get($h,$i));$i++)$cols[]=$get($h,$i);$rows=[];for($i=$h+1;$i<count($sheet)&&$range($get($i,$c));$i++){$cells=[];foreach($cols as $k=>$v)$cells[]=$get($i,$c+$k+1);if(!array_filter($cells,static fn($v)=>preg_match('/^(XS|S|M|L|XL|[2-4]XL)$/D',$v)))break;foreach($cells as $v)if($v!==''&&!preg_match('/^(XS|S|M|L|XL|[2-4]XL)$/D',$v))throw new RuntimeException('Size không hợp lệ: '.$title);$rows[]=array_merge([$get($i,$c)],$cells);}if(!$rows)throw new RuntimeException('Bảng size trống: '.$title);$result[]=['title'=>$title,'skus'=>array_values(array_unique($codes[0])),'cols'=>$cols,'rows'=>$rows];}
 return $result;
}
function size_source_specs(array $sheet,array $charts):array {
 $get=static fn($r,$c)=>trim((string)($sheet[$r][$c]??''));$isSize=static fn($v)=>preg_match('/^(XS|S|M|L|XL|[2-4]XL)$/D',$v);$heads=[];$out=[];
 foreach($sheet as $r=>$row)foreach($row as $c=>$title)if(preg_match('/^THÔNG SỐ/iu',trim($title))){preg_match_all('/\b[A-Z]{1,8}\d{1,6}\b/u',mb_strtoupper($title,'UTF-8'),$codes);if($codes[0])$heads[]=['r'=>$r,'c'=>$c,'codes'=>$codes[0]];}
 foreach($heads as $head){$r=$head['r'];$c=$head['c'];$cols=[];for($h=$r;$h<=$r+1;$h++){$candidate=[];for($i=$c+1;$isSize($get($h,$i));$i++)$candidate[]=$get($h,$i);if(count($candidate)>=3){$cols=$candidate;break;}}if(!$cols){$female=false;foreach($head['codes'] as $sku)if(($charts[$sku]['gender']??'')==='Nữ')$female=true;$cols=$female?['XS','S','M','L','XL','2XL']:['S','M','L','XL','2XL','3XL','4XL'];}$end=count($sheet);foreach($heads as $next)if($next['r']>$r&&abs($next['c']-$c)<8)$end=min($end,$next['r']);$rows=[];
 for($i=$r+1;$i<$end;$i++){$label=$get($i,$c);if($label===''||preg_match('/^FORM|^ÁO /iu',$label))continue;$values=[];foreach($cols as $k=>$v)$values[]=$get($i,$c+$k+1);if(!array_filter($values,static fn($v)=>preg_match('/^\d+(?:[.,]\d+)?$/D',$v)))continue;foreach($values as $v)if($v!==''&&!preg_match('/^\d+(?:[.,]\d+)?$/D',$v))throw new RuntimeException('Thông số size chưa đọc rõ');$rows[]=array_merge([$label],$values);}if(!$rows)throw new RuntimeException('Bảng thông số trống');foreach($head['codes'] as $sku)foreach($sku==='E1234'?['E1','E2','E3','E4']:[$sku] as $target)$out[$target][]=['cols'=>$cols,'rows'=>$rows];}
 if(!$out)throw new RuntimeException('Không tìm thấy bảng thông số');return $out;
}
function size_monitor_source_sync(PDO $db,array $config,array $rows):array {
 size_monitor_schema($db);$state=$db->query('SELECT * FROM size_monitor_state')->fetch(PDO::FETCH_ASSOC);if(!$state)throw new RuntimeException('Bật mốc theo dõi trước');$charts=[];foreach(['nam','nu','spec'] as $name){$url=$config[$name]??'';if(!preg_match('~^https://docs\.google\.com/spreadsheets/d/[A-Za-z0-9_-]+/gviz/tq\?tqx=out:csv&gid=\d+$~D',$url))throw new RuntimeException('Nguồn Google Sheets không hợp lệ');$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>25,CURLOPT_MAXREDIRS=>3]);$csv=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($status!==200||!is_string($csv)||strlen($csv)>2000000||preg_match('/^\s*</',$csv))throw new RuntimeException('Không đọc được bảng size '.$name);$csv=ltrim($csv,"\xEF\xBB\xBF");$fp=fopen('php://temp','w+');fwrite($fp,$csv);rewind($fp);$sheet=[];while(($line=fgetcsv($fp))!==false)$sheet[]=$line;fclose($fp);if($name==='spec'){$specs=size_source_specs($sheet,$charts);foreach($charts as $sku=>&$chart){$value=json_decode($chart['chart'],true);$value['garmentMeasurements']=$specs[$sku]??[];$chart['chart']=json_encode($value,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}unset($chart);continue;}$blocks=size_source_blocks($sheet);if(!$blocks)throw new RuntimeException('Không tìm thấy bảng size '.$name);foreach($blocks as $b)foreach($b['skus'] as $sku){if($sku==='E1234')$targets=['E1','E2','E3','E4'];else $targets=[$sku];foreach($targets as $target){$chart=json_encode(['cols'=>$b['cols'],'rows'=>$b['rows']],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(isset($charts[$target])&&$charts[$target]['chart']!==$chart)throw new RuntimeException('Có nhiều bảng size khác nhau cho '.$target);$charts[$target]=['chart'=>$chart,'title'=>$b['title'],'gender'=>$name==='nam'?'Nam':'Nữ'];}}}
 $now=gmdate('c');$db->beginTransaction();try{$changed=false;$changedSkus=[];$count=0;foreach($charts as $sku=>$c){$hash=hash('sha256',$c['chart']);$q=$db->prepare("SELECT * FROM size_chart_versions WHERE sku=? AND source_hash<>'' AND ended_at='' ORDER BY id DESC LIMIT 1");$q->execute([$sku]);$old=$q->fetch(PDO::FETCH_ASSOC);if($old&&$old['source_hash']===$hash)continue;$changed=$changed||!!$old;if($old)$changedSkus[]=$sku;$db->prepare("UPDATE size_chart_versions SET ended_at=?,date_to=?,updated_at=? WHERE sku=? AND source_hash<>'' AND ended_at=''")->execute([$now,substr($now,0,10),$now,$sku]);$local=(new DateTimeImmutable($now))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d');$db->prepare("INSERT INTO size_chart_versions(sku,name,date_from,date_to,chart,note,actor,created_at,updated_at,applied_at,ended_at,source_hash) VALUES(?,?,?,'',?,?,?,?,?,?,'',?)")->execute([$sku,$c['title'].' · '.$local,$local,$c['chart'],'Tự lưu khi web ghi nhận nội dung mới từ nguồn tiện ích; không hồi tố đơn cũ.','source-sync',$now,$now,$now,$hash]);$count++;}
  if($state['last_sync']!==''&&$changedSkus){$hold=$db->prepare("UPDATE size_monitor_assignments SET version_id=0,reason='Đơn xuất hiện trong khoảng nguồn đổi bảng size; cần xác nhận trước khi dùng làm mẫu.' WHERE sku=? AND order_id IN(SELECT id FROM size_monitor_orders WHERE eligible=1 AND first_seen>=? AND first_seen<=?)");foreach($changedSkus as $sku)$hold->execute([$sku,$state['last_sync'],$now]);}
  size_monitor_enroll($db,$rows,false,$changed,$now);$db->prepare("UPDATE size_monitor_state SET last_sync=?,source_error='' WHERE id=1")->execute([$now]);$db->commit();return ['changed'=>$count,'charts'=>count($charts),'at'=>$now];
 }catch(Throwable $e){$db->rollBack();throw $e;}
}

function size_monitor_time(string $value):string {return $value===''?'Đang áp dụng':(new DateTimeImmutable($value))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('H:i:s d/m/Y');}
function size_monitor_current_rows(PDO $db,array $rows):array {
 $active=[];foreach($db->query("SELECT id,sku FROM size_chart_versions WHERE applied_at<>'' AND ended_at=''") as $v)$active[$v['sku']]=(int)$v['id'];$out=[];foreach($rows as $r){$r['items']=array_values(array_filter($r['items'],static fn($i)=>isset($active[$i['sku']])&&(int)($r['sizeCharts'][$i['sku']]['id']??0)===$active[$i['sku']]));if($r['items'])$out[]=$r;}return $out;
}
function size_monitor_chart_html(string $raw):string {
 $chart=json_decode($raw,true);if(!is_array($chart)||!isset($chart['cols'],$chart['rows']))return '<pre>'.h($raw).'</pre>';$render=static function($grid,$axis){$html='<div class="mkt-table-wrap"><table><thead><tr><th>'.h($axis).'</th>';foreach($grid['cols'] as $c)$html.='<th>'.h($c).'</th>';$html.='</tr></thead><tbody>';foreach($grid['rows'] as $r){$html.='<tr>';foreach($r as $c)$html.='<td>'.h($c).'</td>';$html.='</tr>';}$html.='</tbody></table></div>';return $html;};$html=$render($chart,'Cao (cm) / Nặng (kg)');foreach($chart['garmentMeasurements']??[] as $grid)$html.='<h4>Thông số sản phẩm</h4>'.$render($grid,'Thông số / Size');return $html;
}
